package com.atlasiq.twin;
import com.atlasiq.persistence.*;import com.atlasiq.qir.*;import jakarta.enterprise.context.ApplicationScoped;import java.util.*;
@ApplicationScoped public class ArchitectureMemoryService {private final AnalysisStore store;public ArchitectureMemoryService(AnalysisStore s){store=s;}public Memory remember(String repository,String system,String nodeId,int limit){List<StoredAnalysis>h=store.history(repository,system,Math.min(200,Math.max(2,limit)));List<Moment>moments=new ArrayList<>();QirNode previous=null;for(StoredAnalysis a:h.reversed()){QirNode n=a.model().nodes().stream().filter(x->x.id().equals(nodeId)).findFirst().orElse(null);if(n!=null&&(previous==null||!Objects.equals(previous,n))){moments.add(new Moment(a.id(),a.createdAt(),n,previous==null?"APPEARED":"CHANGED"));previous=n;}}return new Memory(repository,nodeId,moments.isEmpty()?null:moments.getFirst().at(),moments.isEmpty()?null:moments.getLast().at(),List.copyOf(moments));}public record Moment(String analysisId,java.time.Instant at,QirNode node,String event){}public record Memory(String repository,String nodeId,java.time.Instant firstSeen,java.time.Instant lastChanged,List<Moment>timeline){}}
